#include <iostream>
#include <vector>
using namespace std;

int main() {
    long long n;
    int k;
    cin >> n >> k;

    vector<int> digits;
    while (n > 0) {
        digits.push_back(n % k);
        n /= k;
    }

    vector<vector<long long>> matrix(k + 1, vector<long long>(k + 1, 0));
    for (int j = 0; j <= k; ++j) {
        matrix[0][j] = 1;
        matrix[j][j] = 1;
    }

    auto multiply_matrices = [&](const vector<vector<long long>> &A, const vector<vector<long long>> &B) {
        vector<vector<long long>> result(k + 1, vector<long long>(k + 1, 0));
        for (int i = 0; i <= k; ++i)
            for (int j = 0; j <= k; ++j)
                for (int l = 0; l <= k; ++l)
                    result[i][j] = (result[i][j] + A[i][l] * B[l][j]) % 1000000007;
        return result;
    };

    auto matrix_power = [&](vector<vector<long long>> base, long long exp) {
        vector<vector<long long>> res(k + 1, vector<long long>(k + 1, 0));
        for (int i = 0; i <= k; ++i) res[i][i] = 1;
        while (exp > 0) {
            if (exp & 1) res = multiply_matrices(res, base);
            base = multiply_matrices(base, base);
            exp >>= 1;
        }
        return res;
    };

    vector<vector<long long>> A = matrix;
    long long total_sum = 0;
    for (int i = (int)digits.size() - 1; i >= 0; --i) {
        for (int j = 0; j < digits[i]; ++j) {
            auto temp = matrix_power(A, (j + total_sum) % k);
            for (int x = 0; x <= k; ++x)
                for (int y = 0; y <= k; ++y)
                    matrix[x][y] = (matrix[x][y] + temp[x][y]) % 1000000007;
        }
        total_sum = (total_sum + digits[i]) % k;
    }

    long long answer = 0;
    for (int i = 0; i <= k; ++i) {
        answer = (answer + matrix[i][k]) % 1000000007;
    }
    cout << answer << "\n";
    return 0;
}
